import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/WiFi%E3%83%AB%E3%83%BC%E3%82%BF%E3%83%BC.html","title":"WiFiルーター","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.13,"words":339},"filePathRelative":"WiFiルーター.md"}`),a={name:`WiFiルーター.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="wifiルーター" tabindex="-1"><a class="header-anchor" href="#wifiルーター"><span>WiFiルーター</span></a></h1><p><a href="./WiMax.html">WiMax</a>, <a href="./楽天モバイル.html">楽天モバイル</a></p><h2 id="zte-speed-wi-fi-home-5g-l13-ztr02-2026-06-19〜" tabindex="-1"><a class="header-anchor" href="#zte-speed-wi-fi-home-5g-l13-ztr02-2026-06-19〜"><span>ZTE Speed Wi-Fi HOME 5G L13(ZTR02) 2026-06-19〜</span></a></h2><p><a href="https://a.r10.to/h5qpp7" target="_blank" rel="noopener noreferrer">楽天: ZTE Speed Wi-Fi HOME 5G L13</a></p><p>13,847円に1300ポイントくらいがついて買う。12500円相当くらいか。</p><p>設定はこのサイトを参考に＞<a href="https://afrevi.co.jp/speedwifihome5g-l13-rakutenmobile" target="_blank" rel="noopener noreferrer">「図解」Speed WiFi Home5G L13の楽天モバイル設定方法-最新版 - 株式会社AFREVI（アフレビ）</a></p><p>今の所問題無さそう。</p><p>みんそくでMacBookからの計測結果。</p><table><thead><tr><th>種類</th><th>測定結果</th></tr></thead><tbody><tr><td>Jitter</td><td>179.23ms</td></tr><tr><td>Ping</td><td>45.0ms</td></tr><tr><td>下り</td><td>44.1Mbps(少し速い)</td></tr><tr><td>上り</td><td>11.23Mbps(あまり速くない)</td></tr></tbody></table><p>あまりスマホからのデザリングと変わらんな。 夜の不安定な時間にこれならまぁいいか、という気もするが。</p><p>そして5Gは入ってなさそう。一応5G圏内のはずなんだがな〜。</p><h2 id="galaxy-5g-mobile-wifi-scr01-2023-08-26〜" tabindex="-1"><a class="header-anchor" href="#galaxy-5g-mobile-wifi-scr01-2023-08-26〜"><span>Galaxy 5G Mobile WiFi (SCR01) 2023-08-26〜</span></a></h2><ul><li><a href="https://karino2.github.io/2024/10/09/uq_wimax_to_rakuten_2line.html" target="_blank" rel="noopener noreferrer">UQ WiMaxから楽天モバイル2回線に乗り換え - なーんだ、ただの水たまりじゃないか</a></li></ul><p><a href="./WiMax.html">WiMax</a>の方に記述あり。UQ-WiMaxの2円で買える時期に契約して入手。</p><p>Speed Wi-Fi 5G X11がひどすぎてうんざりだったので、Galaxy 5Gは割と満足していたが、2026-06に不安定なことがちょくちょくでてきた。 Rakuten WiFi Pocket 2Cの方が安定している。</p><h2 id="speed-wi-fi-5g-x11-2022-06〜2023-08-26" tabindex="-1"><a class="header-anchor" href="#speed-wi-fi-5g-x11-2022-06〜2023-08-26"><span>Speed Wi-Fi 5G X11 2022-06〜2023-08-26</span></a></h2><p>2022-06の下旬くらいから<a href="./WiMax.html">WiMax</a>で使っていた。</p><p><a href="https://karino2.github.io/2022/07/01/june3_dailylife.html" target="_blank" rel="noopener noreferrer">6月下旬の雑記 - なーんだ、ただの水たまりじゃないか</a></p><p>契約の経緯は書いていないが、当時は引っ越しとか生活水準を上げようと考えていた時期なので、その一環だと思う。</p><p><a href="https://karino2.github.io/2022/06/21/lifelevelup_planning.html" target="_blank" rel="noopener noreferrer">生活水準向上委員会 - なーんだ、ただの水たまりじゃないか</a></p><p>確か楽天回線は当時アップロードがめちゃ遅くてSlackにバイナリ貼ったりに支障があったのとDMMとかの大きめの動画は切れがちだったんだよな。</p><p>X11はカバンに入れて電車に乗ったりすると通信が不安定な所でめちゃ熱くなってかなり怖い感じで、 1年くらいしたら熱すぎですとか言って勝手にシャットダウンするようになる。 通信も不安定だしめちゃ満足度低いルーターだった。</p><h2 id="rakuten-wifi-pocket-2c-2022-05〜" tabindex="-1"><a class="header-anchor" href="#rakuten-wifi-pocket-2c-2022-05〜"><span>Rakuten WiFi Pocket 2C 2022-05〜</span></a></h2><p>2回線目も使ってなければ0円だった時代に1円で購入。</p><p><a href="https://karino2.github.io/2022/05/01/rakuten_mobile_wifi.html" target="_blank" rel="noopener noreferrer">楽天モバイルのモバイルWiFiルーターをメインネットワーク環境にした - なーんだ、ただの水たまりじゃないか</a></p><p>軽くて小さいが、通信が遅くて動画とかはつまりがちだったのとアップロードが遅すぎた。 ただこれは回線の問題でその後だいぶ改善されている気がする。ルーターとしては割と悪くないのかもしれない。</p><p>Galaxy 5G WiFiが2026/06あたりに不安定になってたまに引っ張り出して使っている。</p><p>しばらく使うと詰る感じになってきた。どうも充電がいっぱいになってバッテリ保護のために充電をとめます、 という表示が出てる時にそうなっている事が多い気が？(濡れ衣かもしれないが)</p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};